const tabId = 1148881640;

const result = await browserjs(tabId, () => {
  // Find all elements around chart timeframes
  const elements = Array.from(document.querySelectorAll('*')).filter(el => {
    return ['1D', '7D', '1M', '1Y', 'ALL', 'YTD'].includes(el.textContent?.trim());
  });
  return elements.map(el => ({
    tagName: el.tagName,
    text: el.textContent?.trim(),
    className: el.className,
    parentText: el.parentElement?.textContent?.trim().slice(0, 100),
    outerHTML: el.outerHTML.slice(0, 200)
  }));
});

console.log("Timeframe elements:", JSON.stringify(result, null, 2));

const tabId = 1148881640;

const containerInfo = await browserjs(tabId, () => {
  const span1M = Array.from(document.querySelectorAll('span')).find(el => el.textContent?.trim() === '1M');
  if (!span1M) return "No 1M span found";
  let parent = span1M;
  for (let i = 0; i < 5; i++) {
    if (parent.parentElement) parent = parent.parentElement;
  }
  return {
    parentTag: parent.tagName,
    parentClass: parent.className,
    parentHTML: parent.outerHTML.slice(0, 2000),
    allButtonsOrTabs: Array.from(parent.querySelectorAll('button, li, [role="tab"], [role="button"], a, div')).map(el => ({
      tag: el.tagName,
      role: el.getAttribute('role'),
      text: el.textContent?.trim(),
      title: el.getAttribute('title')
    })).filter(x => x.text && x.text.length < 20)
  };
});

console.log("Container Info:", JSON.stringify(containerInfo, null, 2));

